-- School-scoped moderated community. No public profile or direct student chat.
begin;
create table app.community_rooms(school_id uuid not null,id uuid not null default gen_random_uuid(),class_id uuid not null,name text not null check(length(btrim(name))between 1 and 200),type text not null check(type in('CLASS','GROUP')),owner_id uuid not null,status text not null default'ACTIVE'check(status in('ACTIVE','ARCHIVED')),policy_version integer not null default 1 check(policy_version=1),created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),foreign key(school_id,class_id)references app.classes(school_id,id),foreign key(school_id,owner_id)references app.memberships(school_id,actor_id));
create unique index community_class_room_unique on app.community_rooms(school_id,class_id)where type='CLASS'and status='ACTIVE';
create table app.community_members(school_id uuid not null,room_id uuid not null,actor_id uuid not null,status text not null check(status in('active','revoked')),configured_by uuid not null,primary key(school_id,room_id,actor_id),foreign key(school_id,room_id)references app.community_rooms(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id),foreign key(school_id,configured_by)references app.memberships(school_id,actor_id));
create table app.community_posts(school_id uuid not null,id uuid not null default gen_random_uuid(),room_id uuid not null,actor_id uuid not null,body text not null check(length(btrim(body))between 1 and 4000),reply_to_id uuid,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,id,room_id),foreign key(school_id,room_id)references app.community_rooms(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id),foreign key(school_id,reply_to_id,room_id)references app.community_posts(school_id,id,room_id));
create table app.community_reactions(school_id uuid not null,post_id uuid not null,actor_id uuid not null,reaction text not null check(reaction in('THANKS','HELPFUL','ENCOURAGE')),active boolean not null,primary key(school_id,post_id,actor_id,reaction),foreign key(school_id,post_id)references app.community_posts(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id));
create table app.community_reports(school_id uuid not null,id uuid not null default gen_random_uuid(),post_id uuid not null,actor_id uuid not null,reason text not null check(length(btrim(reason))between 1 and 1000),created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,post_id,actor_id),foreign key(school_id,post_id)references app.community_posts(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id));
create table app.community_moderations(school_id uuid not null,id uuid not null default gen_random_uuid(),post_id uuid not null,action text not null check(action in('HIDE','RESTORE')),reason text not null check(length(btrim(reason))between 1 and 1000),actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),foreign key(school_id,post_id)references app.community_posts(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id));
create table app.community_restrictions(school_id uuid not null,id uuid not null default gen_random_uuid(),room_id uuid not null,target_actor_id uuid not null,restriction text not null check(restriction in('MUTED','RESTRICTED','NONE')),reason text not null check(length(btrim(reason))between 1 and 1000),actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),foreign key(school_id,room_id)references app.community_rooms(school_id,id),foreign key(school_id,target_actor_id)references app.memberships(school_id,actor_id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id));
create table app.community_announcements(school_id uuid not null references app.schools(id),id uuid not null default gen_random_uuid(),class_id uuid,title text not null check(length(btrim(title))between 1 and 200),body text not null check(length(btrim(body))between 1 and 4000),parent_visible boolean not null default false,actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),foreign key(school_id,class_id)references app.classes(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id));
create table app.community_notification_reads(school_id uuid not null,announcement_id uuid not null,actor_id uuid not null,read_at timestamptz not null default clock_timestamp(),primary key(school_id,announcement_id,actor_id),foreign key(school_id,announcement_id)references app.community_announcements(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id));
create table internal.community_broadcast_receipts(event_id uuid primary key references internal.outbox_events(id),broadcast_at timestamptz not null default clock_timestamp());
create index community_posts_room_idx on app.community_posts(school_id,room_id,id);create index community_restriction_latest_idx on app.community_restrictions(school_id,room_id,target_actor_id,created_at desc,id desc);create index community_moderation_latest_idx on app.community_moderations(school_id,post_id,created_at desc,id desc);
create function "authorization".community_member(target_school uuid,target_actor uuid)returns text language sql stable security definer set search_path=''as $$select m.role from app.memberships m join app.schools s on s.id=m.school_id where m.school_id=target_school and m.actor_id=target_actor and s.status='active'and m.status='active'and m.effective_from<=now()and(m.effective_to is null or m.effective_to>now())and exists(select 1 from app.entitlements e where e.school_id=target_school and e.code='community'and e.enabled and e.effective_from<=now()and(e.effective_to is null or e.effective_to>now()))$$;
create function "authorization".community_class(target_school uuid,target_class uuid,target_actor uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce(exists(select 1 from app.classes c where c.school_id=target_school and c.id=target_class and c.status='active')and(
 "authorization".community_member(target_school,target_actor)='admin'or("authorization".community_member(target_school,target_actor)='teacher'and exists(select 1 from app.teacher_assignments t where t.school_id=target_school and t.class_id=target_class and t.teacher_actor_id=target_actor and t.status='active'and t.effective_from<=now()and(t.effective_to is null or t.effective_to>now())))or("authorization".community_member(target_school,target_actor)='student'and exists(select 1 from app.enrollments e where e.school_id=target_school and e.class_id=target_class and e.student_actor_id=target_actor and e.status='active'and e.effective_from<=now()and(e.effective_to is null or e.effective_to>now())))),false)$$;
create function "authorization".community_staff(target_school uuid,target_room uuid,target_actor uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce(exists(select 1 from app.community_rooms r where r.school_id=target_school and r.id=target_room and r.status='ACTIVE'and"authorization".community_class(r.school_id,r.class_id,target_actor)and("authorization".community_member(target_school,target_actor)='admin'or(r.owner_id=target_actor and"authorization".community_member(target_school,target_actor)='teacher'))),false)$$;
create function "authorization".community_restriction(target_school uuid,target_room uuid,target_actor uuid)returns text language sql stable security definer set search_path=''as $$select coalesce((select restriction from app.community_restrictions r where r.school_id=target_school and r.room_id=target_room and r.target_actor_id=target_actor order by created_at desc,id desc limit 1),'NONE')$$;
create function "authorization".community_room(target_school uuid,target_room uuid,target_actor uuid,write_access boolean)returns boolean language sql stable security definer set search_path=''as $$select coalesce(exists(select 1 from app.community_rooms r where r.school_id=target_school and r.id=target_room and r.status='ACTIVE'and"authorization".community_class(target_school,r.class_id,target_actor)and(r.type='CLASS'or"authorization".community_staff(target_school,r.id,target_actor)or exists(select 1 from app.community_members m where m.school_id=target_school and m.room_id=r.id and m.actor_id=target_actor and m.status='active'))and("authorization".community_staff(target_school,r.id,target_actor)or("authorization".community_restriction(target_school,r.id,target_actor)<>'RESTRICTED'and(not write_access or"authorization".community_restriction(target_school,r.id,target_actor)='NONE')))),false)$$;
create function "authorization".community_announcement(target_school uuid,target_class uuid,parent_allowed boolean,target_actor uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce("authorization".community_member(target_school,target_actor)is not null and(case when"authorization".community_member(target_school,target_actor)='parent'then parent_allowed and exists(select 1 from app.parent_relationships r where r.school_id=target_school and r.parent_actor_id=target_actor and r.status='active'and r.effective_from<=now()and(r.effective_to is null or r.effective_to>now())and"authorization".community_member(target_school,r.student_actor_id)='student'and(target_class is null or exists(select 1 from app.enrollments e where e.school_id=target_school and e.class_id=target_class and e.student_actor_id=r.student_actor_id and e.status='active'and e.effective_from<=now()and(e.effective_to is null or e.effective_to>now()))))else target_class is null or"authorization".community_class(target_school,target_class,target_actor)end),false)$$;
create function internal.community_post_hidden(target_school uuid,target_post uuid)returns boolean language sql stable security definer set search_path=''as $$select coalesce((select action='HIDE'from app.community_moderations m where m.school_id=target_school and m.post_id=target_post order by created_at desc,id desc limit 1),false)$$;
create function internal.community_command(command_name text,target uuid,payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();room app.community_rooms;post app.community_posts;announcement app.community_announcements;room_id uuid;reservation jsonb;rid uuid;response jsonb;event_name text;member_id uuid;scope text;fields text[];
begin
 if not"authorization".can_access_school(school)or"authorization".community_member(school,actor)is null then raise exception 'Community denied'using errcode='42501';end if;
 fields:=case command_name when'room.create'then array['classId','name','type','memberIds']when'member.configure'then array['actorId','status','confirmAccessChange']when'post.create'then array['body','replyToId']when'reaction.configure'then array['reaction','active']when'report.create'then array['reason']when'post.moderate'then array['action','reason','confirmModeration']when'room.restrict'then array['actorId','restriction','reason','confirmModeration']when'announcement.create'then array['classId','title','body','parentVisible']when'notification.read'then array[]::text[]else null end;
 if fields is null or payload is null or jsonb_typeof(payload)<>'object'or payload-fields<>'{}'::jsonb or octet_length(payload::text)>16384 then raise exception 'Invalid community fields'using errcode='22023';end if;
 if command_name in('room.create','announcement.create')then
  if"authorization".community_member(school,actor)not in('admin','teacher')then raise exception 'Community author denied'using errcode='42501';end if;
  if(payload->>'classId')is null then if command_name='room.create'or"authorization".community_member(school,actor)<>'admin'then raise exception 'School announcement author denied'using errcode='42501';end if;else if not"authorization".community_class(school,(payload->>'classId')::uuid,actor)then raise exception 'Current class author required'using errcode='42501';end if;end if;
 elsif command_name='notification.read'then
  select*into announcement from app.community_announcements where school_id=school and id=target;
  if not found or not"authorization".community_announcement(school,announcement.class_id,announcement.parent_visible,actor)then raise exception 'Announcement receipt denied'using errcode='42501';end if;
 elsif command_name in('member.configure','post.create','room.restrict')then
  room_id:=target;select*into room from app.community_rooms where school_id=school and id=room_id for update;
  if not found or not"authorization".community_room(school,room_id,actor,command_name='post.create')then raise exception 'Room current access denied'using errcode='42501';end if;
  if command_name<>'post.create'and not"authorization".community_staff(school,room_id,actor)then raise exception 'Room moderation denied'using errcode='42501';end if;
 else
  select*into post from app.community_posts where school_id=school and id=target;
  if not found then raise exception 'Post denied'using errcode='42501';end if;room_id:=post.room_id;
  perform 1 from app.community_rooms where school_id=school and id=room_id for update;
  if not"authorization".community_room(school,room_id,actor,command_name='reaction.configure')then raise exception 'Post current access denied'using errcode='42501';end if;
  if command_name='post.moderate'and not"authorization".community_staff(school,room_id,actor)then raise exception 'Moderation denied'using errcode='42501';end if;
  if command_name='reaction.configure'and internal.community_post_hidden(school,post.id)then raise exception 'Hidden post reaction denied'using errcode='42501';end if;
 end if;
 if command_name not in('room.create','member.configure','post.create','reaction.configure','report.create','post.moderate','room.restrict','announcement.create','notification.read')then raise exception 'Unknown community command'using errcode='22023';end if;
 reservation:=internal.begin_command(command_key,'community.'||command_name,fingerprint);if reservation->>'state'='COMPLETED'then return reservation->'response';elsif reservation->>'state'<>'NEW'then raise exception 'Community command in progress'using errcode='22023';end if;
 -- Count committed audited actions only; repeated keys return before the limiter. Serialize per actor.
 perform pg_advisory_xact_lock(hashtextextended(school::text||':community-rate:'||actor::text,0));
 if command_name in('post.create','reaction.configure','report.create')and(select count(*)from internal.audit_events where school_id=school and actor_id=actor and action in('community.post.create','community.reaction.configure','community.report.create')and occurred_at>clock_timestamp()-interval'1 minute')>=10 then raise exception 'Community rate limit'using errcode='P0003';end if;
 if command_name='room.create'then
  if payload->>'type'not in('CLASS','GROUP')or length(btrim(payload->>'name'))not between 1 and 200 or jsonb_array_length(payload->'memberIds')>100 then raise exception 'Invalid room definition'using errcode='22023';end if;
  insert into app.community_rooms(school_id,class_id,name,type,owner_id)values(school,(payload->>'classId')::uuid,payload->>'name',payload->>'type',actor)returning id into rid;room_id:=rid;
  for member_id in select value::uuid from jsonb_array_elements_text(payload->'memberIds')loop
   if not"authorization".community_class(school,(payload->>'classId')::uuid,member_id)or"authorization".community_member(school,member_id)not in('student','teacher')then raise exception 'Current class group member required'using errcode='42501';end if;
   insert into app.community_members(school_id,room_id,actor_id,status,configured_by)values(school,rid,member_id,'active',actor)on conflict do nothing;
  end loop;
 elsif command_name='member.configure'then
  if room.type<>'GROUP'or(payload->>'actorId')is null or(payload->>'confirmAccessChange')::boolean is distinct from true or payload->>'status'not in('active','revoked')or not"authorization".community_class(school,room.class_id,(payload->>'actorId')::uuid)then raise exception 'Current group member confirmation required'using errcode='42501';end if;
  insert into app.community_members(school_id,room_id,actor_id,status,configured_by)values(school,room_id,(payload->>'actorId')::uuid,payload->>'status',actor)on conflict(school_id,room_id,actor_id)do update set status=excluded.status,configured_by=excluded.configured_by;rid:=(payload->>'actorId')::uuid;
 elsif command_name='post.create'then
  if payload->>'body'is null or length(btrim(payload->>'body'))not between 1 and 4000 then raise exception 'Post text required'using errcode='22023';end if;
  if payload->>'replyToId'is not null and not exists(select 1 from app.community_posts p where p.school_id=school and p.id=(payload->>'replyToId')::uuid and p.room_id=room_id and not internal.community_post_hidden(school,p.id))then raise exception 'Current visible reply source required'using errcode='42501';end if;
  insert into app.community_posts(school_id,room_id,actor_id,body,reply_to_id)values(school,room_id,actor,payload->>'body',(payload->>'replyToId')::uuid)returning id into rid;
 elsif command_name='reaction.configure'then
  if payload->>'reaction'not in('THANKS','HELPFUL','ENCOURAGE')or(payload->>'active')::boolean is null then raise exception 'Safe reaction required'using errcode='22023';end if;
  insert into app.community_reactions(school_id,post_id,actor_id,reaction,active)values(school,target,actor,payload->>'reaction',(payload->>'active')::boolean)on conflict(school_id,post_id,actor_id,reaction)do update set active=excluded.active;rid:=target;
 elsif command_name='report.create'then
  if payload->>'reason'is null or length(btrim(payload->>'reason'))not between 1 and 1000 then raise exception 'Report reason required'using errcode='22023';end if;
  insert into app.community_reports(school_id,post_id,actor_id,reason)values(school,target,actor,payload->>'reason')on conflict(school_id,post_id,actor_id)do nothing returning id into rid;
  if rid is null then select r.id into rid from app.community_reports r where r.school_id=school and r.post_id=target and r.actor_id=actor;end if;
 elsif command_name='post.moderate'then
  if(payload->>'confirmModeration')::boolean is distinct from true or payload->>'action'not in('HIDE','RESTORE')or length(btrim(payload->>'reason'))not between 1 and 1000 then raise exception 'Human moderation required'using errcode='22023';end if;
  insert into app.community_moderations(school_id,post_id,action,reason,actor_id)values(school,target,payload->>'action',payload->>'reason',actor)returning id into rid;
 elsif command_name='room.restrict'then
  if(payload->>'confirmModeration')::boolean is distinct from true or payload->>'restriction'not in('MUTED','RESTRICTED','NONE')or length(btrim(payload->>'reason'))not between 1 and 1000 or not"authorization".community_class(school,room.class_id,(payload->>'actorId')::uuid)or(payload->>'actorId')::uuid=room.owner_id or"authorization".community_member(school,(payload->>'actorId')::uuid)='admin'then raise exception 'Current member moderation required'using errcode='42501';end if;
  insert into app.community_restrictions(school_id,room_id,target_actor_id,restriction,reason,actor_id)values(school,room_id,(payload->>'actorId')::uuid,payload->>'restriction',payload->>'reason',actor)returning id into rid;
 elsif command_name='announcement.create'then
  insert into app.community_announcements(school_id,class_id,title,body,parent_visible,actor_id)values(school,(payload->>'classId')::uuid,payload->>'title',payload->>'body',(payload->>'parentVisible')::boolean,actor)returning id into rid;
 else
  insert into app.community_notification_reads(school_id,announcement_id,actor_id)values(school,target,actor)on conflict do nothing;rid:=target;
 end if;
 response:=jsonb_build_object('id',rid,'command',command_name);
 if command_name='room.create'then response:=response||jsonb_build_object('roomId',room_id);end if;
 if command_name='post.create'then response:=response||jsonb_build_object('roomId',room_id,'body',payload->>'body','replyToId',payload->>'replyToId','actorId',actor,'createdAt',clock_timestamp(),'status','VISIBLE');end if;
 if command_name='notification.read'then response:=response||jsonb_build_object('status','READ');end if;
 perform internal.append_audit('community.'||command_name,'community',rid,request_id,'succeeded','{}');
 event_name:=case when command_name='post.create'then'community.post_created'when command_name='report.create'then'moderation.reported'else'community.changed'end;
 perform internal.enqueue_event(event_name,'community',rid,1,jsonb_build_object('roomId',room_id),'community:'||md5(actor::text||command_name||command_key));
 perform internal.finish_command(command_key,'community.'||command_name,fingerprint,response);return response;
end$$;
create function internal.community_list(resource text,target_room uuid,filters jsonb)returns jsonb language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();sql text;rows jsonb;items jsonb;lim integer;cursor_id uuid;
begin
 if not"authorization".can_access_school(school)or"authorization".community_member(school,actor)is null then raise exception 'Community denied'using errcode='42501';end if;
 lim:=(filters->>'limit')::integer;cursor_id:=(filters->>'cursor')::uuid;if lim is null or lim not between 1 and 100 then raise exception 'Bounded community query required'using errcode='22023';end if;
 if resource in('roster','posts','reports')and not"authorization".community_room(school,target_room,actor,false)then raise exception 'Room read denied'using errcode='42501';end if;
 if resource='reports'and not"authorization".community_staff(school,target_room,actor)then raise exception 'Report review denied'using errcode='42501';end if;
 case resource
 when'rooms'then sql:='select r.id,jsonb_build_object(''id'',r.id,''classId'',r.class_id,''name'',r.name,''type'',r.type,''ownerId'',r.owner_id,''status'',r.status,''canModerate'',"authorization".community_staff(r.school_id,r.id,$2),''canPost'',"authorization".community_room(r.school_id,r.id,$2,true),''privateTopic'',''cuevo:''||r.school_id::text||'':room:''||r.id::text)row from app.community_rooms r where r.school_id=$1 and "authorization".community_room(r.school_id,r.id,$2,false)';
 when'roster'then sql:='select m.actor_id id,jsonb_build_object(''id'',m.actor_id,''displayName'',p.display_name,''role'',m.role)row from app.memberships m join app.people p on p.school_id=m.school_id and p.actor_id=m.actor_id where m.school_id=$1 and "authorization".community_room(m.school_id,$3,m.actor_id,false)';
 when'posts'then sql:='select p.id,jsonb_build_object(''id'',p.id,''roomId'',p.room_id,''actorId'',p.actor_id,''authorName'',person.display_name,''body'',case when internal.community_post_hidden(p.school_id,p.id)then null else p.body end,''replyToId'',p.reply_to_id,''createdAt'',p.created_at,''status'',case when internal.community_post_hidden(p.school_id,p.id)then ''HIDDEN''else''VISIBLE''end,''reactions'',(select coalesce(jsonb_agg(jsonb_build_object(''reaction'',reaction,''count'',count,''mine'',mine)),''[]''::jsonb)from(select reaction,count(*)count,bool_or(actor_id=$2)mine from app.community_reactions where school_id=p.school_id and post_id=p.id and active group by reaction)counts))row from app.community_posts p join app.people person on person.school_id=p.school_id and person.actor_id=p.actor_id where p.school_id=$1 and p.room_id=$3';
 when'reports'then sql:='select r.id,jsonb_build_object(''id'',r.id,''postId'',r.post_id,''reporterId'',r.actor_id,''reason'',r.reason,''createdAt'',r.created_at)row from app.community_reports r join app.community_posts p on p.school_id=r.school_id and p.id=r.post_id where r.school_id=$1 and p.room_id=$3';
 when'announcements'then sql:='select a.id,jsonb_build_object(''id'',a.id,''classId'',a.class_id,''title'',a.title,''body'',a.body,''parentVisible'',a.parent_visible,''createdAt'',a.created_at,''readAt'',n.read_at)row from app.community_announcements a left join app.community_notification_reads n on n.school_id=a.school_id and n.announcement_id=a.id and n.actor_id=$2 where a.school_id=$1 and "authorization".community_announcement(a.school_id,a.class_id,a.parent_visible,$2)';
 when'notifications'then sql:='select a.id,jsonb_build_object(''id'',a.id,''announcementId'',a.id,''kind'',''ANNOUNCEMENT'',''createdAt'',a.created_at,''readAt'',n.read_at)row from app.community_announcements a left join app.community_notification_reads n on n.school_id=a.school_id and n.announcement_id=a.id and n.actor_id=$2 where a.school_id=$1 and "authorization".community_announcement(a.school_id,a.class_id,a.parent_visible,$2)';
 else raise exception 'Unknown community query'using errcode='22023';end case;
 execute 'select coalesce(jsonb_agg(row order by id),''[]''::jsonb)from(select id,row from('||sql||')scoped where($4::uuid is null or id>$4)order by id limit $5)bounded'into rows using school,actor,target_room,cursor_id,lim+1;
 if octet_length(rows::text)>500000 then raise exception 'Community page requires bounded review'using errcode='22023';end if;
 select coalesce(jsonb_agg(value order by ordinal),'[]'::jsonb)into items from jsonb_array_elements(rows)with ordinality entries(value,ordinal)where ordinal<=lim;
 return jsonb_build_object('items',items,'nextCursor',case when jsonb_array_length(rows)>lim then items->(lim-1)->>'id'else null end);
end$$;
-- Realtime permissions use verified Auth claims and stored current sessions directly. No browser role metadata is trusted.
create function "authorization".community_realtime_topic(channel_topic text)returns boolean language plpgsql stable security definer set search_path=''as $$
declare actor uuid;session uuid;school uuid;room uuid;parts text[];
begin
 actor:=auth.uid();session:=(auth.jwt()->>'session_id')::uuid;parts:=string_to_array(channel_topic,':');
 if actor is null or session is null or array_length(parts,1)<>4 or parts[1]<>'cuevo'or parts[3]<>'room'then return false;end if;school:=parts[2]::uuid;room:=parts[4]::uuid;
 if not exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id where s.id=session and s.user_id=actor and(s.not_after is null or s.not_after>now())and u.deleted_at is null and(u.banned_until is null or u.banned_until<=now()))then return false;end if;
 return "authorization".community_room(school,room,actor,false);
exception when others then return false;
end$$;
-- Managed realtime.messages already has RLS; supautils permits policy DDL but not ALTER TABLE.
do $$begin if not(select relrowsecurity from pg_class where oid='realtime.messages'::regclass)then raise exception 'Realtime RLS required'using errcode='42501';end if;end$$;
create policy cuevo_private_community_receive on realtime.messages for select to authenticated using(extension='broadcast'and private is true and "authorization".community_realtime_topic((select realtime.topic())));
-- No authenticated/anonymous INSERT policy: browser Broadcast and Presence publishing are forbidden.
revoke insert,update,delete on realtime.messages from anon,authenticated;
grant select on realtime.messages to authenticated;
create function internal.process_community_event(target_event uuid,current_lease uuid)returns jsonb language plpgsql security definer set search_path=''as $$
declare e internal.outbox_events;v_room_id uuid;payload jsonb;v_topic text;sent_id uuid;
begin
 select*into e from internal.outbox_events where id=target_event for update;
 if not found or e.state<>'PROCESSING'or e.lease_token is distinct from current_lease or e.lease_until<=clock_timestamp()or e.type not in('community.post_created','community.changed','moderation.reported')then raise exception 'Community event lease invalid'using errcode='22023';end if;
 if exists(select 1 from internal.community_broadcast_receipts where event_id=e.id)then if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception 'Community ack expired'using errcode='22023';end if;return jsonb_build_object('status','DUPLICATE');end if;
 if e.type='community.post_created'then select p.room_id into v_room_id from app.community_posts p where p.school_id=e.school_id and p.id=e.entity_id and p.actor_id=e.actor_id;
 elsif e.type='moderation.reported'then select p.room_id into v_room_id from app.community_reports r join app.community_posts p on p.school_id=r.school_id and p.id=r.post_id where r.school_id=e.school_id and r.id=e.entity_id and r.actor_id=e.actor_id;
 else
  select r.id into v_room_id from app.community_rooms r where r.school_id=e.school_id and r.id=e.entity_id and r.owner_id=e.actor_id;
  if v_room_id is null then select p.room_id into v_room_id from app.community_moderations m join app.community_posts p on p.school_id=m.school_id and p.id=m.post_id where m.school_id=e.school_id and m.id=e.entity_id and m.actor_id=e.actor_id;end if;
  if v_room_id is null then select r.room_id into v_room_id from app.community_restrictions r where r.school_id=e.school_id and r.id=e.entity_id and r.actor_id=e.actor_id;end if;
  if v_room_id is null then select p.room_id into v_room_id from app.community_posts p where p.school_id=e.school_id and p.id=e.entity_id and exists(select 1 from app.community_reactions r where r.school_id=p.school_id and r.post_id=p.id and r.actor_id=e.actor_id);end if;
  if v_room_id is null then select m.room_id into v_room_id from app.community_members m where m.school_id=e.school_id and m.actor_id=e.entity_id and m.configured_by=e.actor_id and m.room_id=(e.metadata->>'roomId')::uuid;end if;
 end if;
 if not exists(select 1 from internal.audit_events a where a.school_id=e.school_id and a.actor_id=e.actor_id and a.entity_id=e.entity_id and a.action like'community.%'and a.outcome='succeeded')then raise exception 'Community event source missing'using errcode='22023';end if;
 if v_room_id is not null then
  v_topic:='cuevo:'||e.school_id::text||':room:'||v_room_id::text;payload:=jsonb_build_object('eventId',e.id,'roomId',v_room_id);
  perform realtime.send(payload,'invalidate',v_topic,true);
  -- realtime.send catches errors; prove a matching stored broadcast before recording delivery.
  select id into sent_id from realtime.messages where topic=v_topic and extension='broadcast'and private is true and event='invalidate'and realtime.messages.payload->>'eventId'=e.id::text order by inserted_at desc limit 1;
  if sent_id is null then raise exception 'Community broadcast requires retry'using errcode='22023';end if;
 end if;
 insert into internal.community_broadcast_receipts(event_id)values(e.id);
 if internal.complete_outbox(e.id,current_lease)is distinct from true then raise exception 'Community ack expired'using errcode='22023';end if;return jsonb_build_object('status','COMPLETED');
end$$;
do $$declare tab text;begin foreach tab in array array['community_rooms','community_members','community_posts','community_reactions','community_reports','community_moderations','community_restrictions','community_announcements','community_notification_reads']loop execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);end loop;foreach tab in array array['community_posts','community_reports','community_moderations','community_restrictions','community_announcements','community_notification_reads']loop execute format('create trigger immutable_history before update or delete on app.%I for each row execute function internal.academic_history_immutable()',tab);end loop;end$$;
create policy community_rooms_read on app.community_rooms for select to cuevo_api using("authorization".community_room(school_id,id,"authorization".actor_id(),false));
create policy community_posts_read on app.community_posts for select to cuevo_api using("authorization".community_room(school_id,room_id,"authorization".actor_id(),false)and not internal.community_post_hidden(school_id,id));
-- Read projections are constrained source functions; raw staff report/roster/history tables are not granted.
revoke all on app.community_rooms,app.community_members,app.community_posts,app.community_reactions,app.community_reports,app.community_moderations,app.community_restrictions,app.community_announcements,app.community_notification_reads from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
revoke all on internal.community_broadcast_receipts from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
revoke execute on function "authorization".community_member(uuid,uuid),"authorization".community_class(uuid,uuid,uuid),"authorization".community_staff(uuid,uuid,uuid),"authorization".community_restriction(uuid,uuid,uuid),"authorization".community_room(uuid,uuid,uuid,boolean),"authorization".community_announcement(uuid,uuid,boolean,uuid),"authorization".community_realtime_topic(text),internal.community_post_hidden(uuid,uuid),internal.community_command(text,uuid,jsonb,text,text,text),internal.community_list(text,uuid,jsonb),internal.process_community_event(uuid,uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.community_command(text,uuid,jsonb,text,text,text),internal.community_list(text,uuid,jsonb)to cuevo_api;
grant execute on function "authorization".community_realtime_topic(text)to authenticated;
grant usage on schema "authorization"to authenticated;
grant execute on function internal.process_community_event(uuid,uuid)to cuevo_worker;
commit;
